// Typed Scala facade for tau2-bench domain 'airline' — the FIXED, committed
// tool surface the agent calls. Generated by gen_tools.py; regenerate the
// committed facades after a tau2 upgrade with:  ./regen_facades.sh
// (which overwrites these files). Each function dispatches to the in-scope
// tau2 tool via Tau.callTool.

val facadeDomain: String = "airline"

// --- data types for structured tool parameters ---
case class FlightInfo(flightNumber: String, date: String)
case class Passenger(firstName: String, lastName: String, dob: String)
case class Payment(paymentId: String, amount: Int)

/** Book a reservation. */
def bookReservation(userId: String, origin: String, destination: String, flightType: String, cabin: String, flights: List[FlightInfo], passengers: List[Passenger], paymentMethods: List[Payment], totalBaggages: Int, nonfreeBaggages: Int, insurance: String): String =
  val args = ujson.Obj()
  args("user_id") = ujson.Str(userId)
  args("origin") = ujson.Str(origin)
  args("destination") = ujson.Str(destination)
  args("flight_type") = ujson.Str(flightType)
  args("cabin") = ujson.Str(cabin)
  args("flights") = ujson.Arr(flights.map(x => ujson.Obj("flight_number" -> ujson.Str(x.flightNumber), "date" -> ujson.Str(x.date)))*)
  args("passengers") = ujson.Arr(passengers.map(x => ujson.Obj("first_name" -> ujson.Str(x.firstName), "last_name" -> ujson.Str(x.lastName), "dob" -> ujson.Str(x.dob)))*)
  args("payment_methods") = ujson.Arr(paymentMethods.map(x => ujson.Obj("payment_id" -> ujson.Str(x.paymentId), "amount" -> ujson.Num(x.amount)))*)
  args("total_baggages") = ujson.Num(totalBaggages)
  args("nonfree_baggages") = ujson.Num(nonfreeBaggages)
  args("insurance") = ujson.Str(insurance)
  Tau.callTool("book_reservation", args)

/** Calculate the result of a mathematical expression. */
def calculate(expression: String): String =
  val args = ujson.Obj()
  args("expression") = ujson.Str(expression)
  Tau.callTool("calculate", args)

/** Cancel the whole reservation. */
def cancelReservation(reservationId: String): String =
  val args = ujson.Obj()
  args("reservation_id") = ujson.Str(reservationId)
  Tau.callTool("cancel_reservation", args)

/** Get the details of a reservation. */
def getReservationDetails(reservationId: String): String =
  val args = ujson.Obj()
  args("reservation_id") = ujson.Str(reservationId)
  Tau.callTool("get_reservation_details", args)

/** Get the details of a user, including their reservations. */
def getUserDetails(userId: String): String =
  val args = ujson.Obj()
  args("user_id") = ujson.Str(userId)
  Tau.callTool("get_user_details", args)

/** Returns a list of all available airports. */
def listAllAirports(): String = Tau.callTool("list_all_airports")

/** Search for direct flights between two cities on a specific date. */
def searchDirectFlight(origin: String, destination: String, date: String): String =
  val args = ujson.Obj()
  args("origin") = ujson.Str(origin)
  args("destination") = ujson.Str(destination)
  args("date") = ujson.Str(date)
  Tau.callTool("search_direct_flight", args)

/** Search for one-stop flights between two cities on a specific date. */
def searchOnestopFlight(origin: String, destination: String, date: String): String =
  val args = ujson.Obj()
  args("origin") = ujson.Str(origin)
  args("destination") = ujson.Str(destination)
  args("date") = ujson.Str(date)
  Tau.callTool("search_onestop_flight", args)

/** Send a certificate to a user. Be careful! */
def sendCertificate(userId: String, amount: Int): String =
  val args = ujson.Obj()
  args("user_id") = ujson.Str(userId)
  args("amount") = ujson.Num(amount)
  Tau.callTool("send_certificate", args)

/** Transfer the user to a human agent, with a summary of the user's issue. Only transfer if - the user explicitly asks for a human agent - given the policy and the available tools, you cannot solve the user's issue. */
def transferToHumanAgents(summary: String): String =
  val args = ujson.Obj()
  args("summary") = ujson.Str(summary)
  Tau.callTool("transfer_to_human_agents", args)

/** Update the baggage information of a reservation. */
def updateReservationBaggages(reservationId: String, totalBaggages: Int, nonfreeBaggages: Int, paymentId: String): String =
  val args = ujson.Obj()
  args("reservation_id") = ujson.Str(reservationId)
  args("total_baggages") = ujson.Num(totalBaggages)
  args("nonfree_baggages") = ujson.Num(nonfreeBaggages)
  args("payment_id") = ujson.Str(paymentId)
  Tau.callTool("update_reservation_baggages", args)

/** Update the flight information of a reservation. */
def updateReservationFlights(reservationId: String, cabin: String, flights: List[FlightInfo], paymentId: String): String =
  val args = ujson.Obj()
  args("reservation_id") = ujson.Str(reservationId)
  args("cabin") = ujson.Str(cabin)
  args("flights") = ujson.Arr(flights.map(x => ujson.Obj("flight_number" -> ujson.Str(x.flightNumber), "date" -> ujson.Str(x.date)))*)
  args("payment_id") = ujson.Str(paymentId)
  Tau.callTool("update_reservation_flights", args)

/** Update the passenger information of a reservation. */
def updateReservationPassengers(reservationId: String, passengers: List[Passenger]): String =
  val args = ujson.Obj()
  args("reservation_id") = ujson.Str(reservationId)
  args("passengers") = ujson.Arr(passengers.map(x => ujson.Obj("first_name" -> ujson.Str(x.firstName), "last_name" -> ujson.Str(x.lastName), "dob" -> ujson.Str(x.dob)))*)
  Tau.callTool("update_reservation_passengers", args)

/** Get the status of a flight. */
def getFlightStatus(flightNumber: String, date: String): String =
  val args = ujson.Obj()
  args("flight_number") = ujson.Str(flightNumber)
  args("date") = ujson.Str(date)
  Tau.callTool("get_flight_status", args)

/** Call this function when you are done with the task. */
def done(): String = Tau.callTool("done")

